import{_ as e,o,c as s,a5 as a}from"./chunks/framework.DGp912Ge.js";const g=JSON.parse('{"title":"Sport Client (Joystick) — C++ Example","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"software/sdk/cpp/sport-client-joy.md","filePath":"software/sdk/cpp/sport-client-joy.md","lastUpdated":1780296047000}'),i={name:"software/sdk/cpp/sport-client-joy.md"};function n(r,t,d,l,c,h){return o(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="sport-client-joystick-—-c-example" tabindex="-1">Sport Client (Joystick) — C++ Example <a class="header-anchor" href="#sport-client-joystick-—-c-example" aria-label="Permalink to &quot;Sport Client (Joystick) — C++ Example&quot;">​</a></h1><p><strong>Source</strong>: <code>rbq_sdk/cpp/example/src/rbq_sport_client_joy.cpp</code></p><p>Drives the robot using a <strong>gamepad / joystick</strong> via the <code>SportClient</code> API.<br> Analog sticks stream continuous <code>Move</code> velocity commands; buttons trigger discrete actions (Damp, StandUp/Down, gait switches, acrobatics).</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Two concurrent parts run together:</p><table tabindex="0"><thead><tr><th>Part</th><th>Rate</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Main thread</strong> (joystick)</td><td>~100 Hz</td><td>Reads joystick events, pushes discrete <code>SportCmd</code> entries onto a queue, updates atomic velocity setpoints</td></tr><tr><td><strong>Control loop thread</strong></td><td>10 Hz</td><td>Drains the command queue first; if empty, calls <code>sport.Move(vx, vy, vyaw)</code></td></tr></tbody></table><p>The control loop calls <code>sport.SetNoReply(true)</code> — commands are sent fire-and-forget without waiting for an RPC acknowledgement.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>RBQ SDK built and installed — see <a href="/RBQ/software/sdk/cpp/overview.html">C++ SDK Overview</a>.</li><li>A Linux joystick device (e.g. Logitech F710) available at <code>/dev/input/js*</code>.</li><li>Robot stack running and reachable on the network interface you pass as <code>argv[1]</code>.</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>From <code>rbq_sdk/cpp/example/</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>Binary: <code>bin/rbq_sport_client_joy</code></p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client_joy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># auto-detect joystick:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client_joy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># explicit joystick device:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_sport_client_joy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/input/js1</span></span></code></pre></div><p>If no joystick path is given, the binary auto-detects <code>js*</code> devices: it prefers a device whose name contains &quot;Logitech&quot;, &quot;gamepad&quot;, &quot;Xbox&quot;, or &quot;wireless&quot;, then falls back to the first available node, then <code>/dev/input/js0</code>.<br> The <code>JOY</code> environment variable can also override the path.</p><h2 id="gamepad-bindings" tabindex="-1">Gamepad bindings <a class="header-anchor" href="#gamepad-bindings" aria-label="Permalink to &quot;Gamepad bindings&quot;">​</a></h2><p>The mapping follows the <strong>Logitech F710 / Xbox layout</strong> recognised by the Linux joystick driver.</p><h3 id="button-chords-checked-first" tabindex="-1">Button chords (checked first) <a class="header-anchor" href="#button-chords-checked-first" aria-label="Permalink to &quot;Button chords (checked first)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Buttons pressed</th><th>Robot action</th></tr></thead><tbody><tr><td><strong>L2 + B</strong></td><td><code>Damp</code> — high-damping emergency stop</td></tr><tr><td><strong>L2 + A</strong> <em>(1st press)</em></td><td><code>StandUp</code> — lock joints in standing position</td></tr><tr><td><strong>L2 + A</strong> <em>(2nd press)</em></td><td><code>StandDown</code> — go prone</td></tr><tr><td><strong>START</strong></td><td><code>DefaultMode</code> — unlock / default gait</td></tr><tr><td><strong>L2 + START</strong></td><td><code>RunningMode</code> — high-speed gait</td></tr><tr><td><strong>L2 + X</strong></td><td><code>RecoveryStand</code> — stand up from fall</td></tr><tr><td><strong>R1 + X</strong></td><td><code>Climb</code> — stair-climb gait</td></tr><tr><td><strong>L1 + X</strong></td><td><strong>not supported on this robot</strong></td></tr><tr><td><strong>L1 + Y</strong></td><td><strong>not supported on this robot</strong></td></tr><tr><td><strong>BACK</strong></td><td><code>StopMove</code> — stop in place</td></tr></tbody></table><h3 id="double-click-bindings" tabindex="-1">Double-click bindings <a class="header-anchor" href="#double-click-bindings" aria-label="Permalink to &quot;Double-click bindings&quot;">​</a></h3><p>A second press within <strong>400 ms</strong> of the first triggers the action.</p><table tabindex="0"><thead><tr><th>Button</th><th>Action</th></tr></thead><tbody><tr><td>Double <strong>X</strong></td><td><code>LeftSideGait</code></td></tr><tr><td>Double <strong>Y</strong></td><td><code>RightSideGait</code></td></tr><tr><td>Double <strong>R1</strong></td><td><strong>not supported on this robot</strong></td></tr><tr><td>Double <strong>R2</strong> (trigger)</td><td><strong>not supported on this robot</strong></td></tr></tbody></table><h3 id="analog-stick-velocity-continuous" tabindex="-1">Analog stick velocity (continuous) <a class="header-anchor" href="#analog-stick-velocity-continuous" aria-label="Permalink to &quot;Analog stick velocity (continuous)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Axis</th><th>Maps to</th><th>Max value</th></tr></thead><tbody><tr><td>Left stick Y (push forward)</td><td><code>vel_x</code> (forward)</td><td>±0.55 m/s</td></tr><tr><td>Left stick X (push left)</td><td><code>vel_y</code> (lateral)</td><td>±0.35 m/s</td></tr><tr><td>Right stick X</td><td><code>vyaw</code> (yaw rate)</td><td>±1.0 rad/s</td></tr></tbody></table><p>A deadzone of <strong>0.12</strong> is applied to all axes before scaling.</p><h2 id="key-implementation-notes" tabindex="-1">Key implementation notes <a class="header-anchor" href="#key-implementation-notes" aria-label="Permalink to &quot;Key implementation notes&quot;">​</a></h2><ul><li><strong><code>lock_toggle_to_prone</code></strong>: <code>L2+A</code> alternates between <code>StandUp</code> and <code>StandDown</code> on successive presses via a boolean toggle — matching the behaviour of the A2 robot&#39;s built-in controller.</li><li><strong>Double-click detection</strong>: A <code>consume_double()</code> lambda tracks the last edge timestamp. If a second edge arrives within <code>kDoubleClickWindow</code> (400 ms), the action fires and the counter resets.</li><li><strong>R2 as virtual button</strong>: The RT trigger (<code>AXIS_RT</code>) is treated as a button by comparing the axis value against 0 — idle is −1, full press is +1.</li><li><strong>Error streak logging</strong>: Consecutive errors are counted; a message is printed every 50 failures to avoid log spam.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/RBQ/software/sdk/cpp/sport-client.html">Sport Client (terminal)</a></li><li><a href="/RBQ/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/software/sdk/cpp/overview.html">C++ SDK Overview</a></li></ul>`,30)])])}const u=e(i,[["render",n]]);export{g as __pageData,u as default};
